/**
 * org group id for ungrouped locations
 */
export const UNGROUPED_ID = 'ungrouped';

/**
 * Converts a decimal to a percentage string
 * @param {number} decimal The decimal value you want converted to a percent
 * @param {number} fixed the number of decimal places, defaulting to 0
 *
 * @returns {string} percentage string
 */
export function toPercent(decimal, fixed = 0) {
  return `${(decimal * 100).toFixed(fixed)}%`;
}

/**
 * A label percent formatter to percent, used by recharts
 * @param {number} value the value to convert to a percent
 *
 * @returns {function} toPercent which converts to a percentage
 */
export function labelPercent(value) {
  if (value === NA) {
    return value;
  }

  return toPercent(value);
}
